-- Class notes synopsis batch 23: Self Heal through Skullcap

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Self Heal</strong> (Prunella vulgaris) is a <strong>lymphatic</strong>, <strong>vulnerary</strong>, and <strong>brain lymphatic</strong> herb containing rosmarinic acid; drains and cools the <strong>liver</strong>; specific affinity to the <strong>brain</strong>. For <strong>concussion</strong>: brain lymph drainage alongside <a href="?herb=2632"><strong>Lion's Mane Mushroom</strong></a> (regenerate nerves, influence cognition), <a href="?herb=109"><strong>Rosemary</strong></a>, and <a href="?herb=165"><strong>Ginkgo</strong></a>. For <strong>thyroid/autoimmune thyroid conditions</strong>: rosmarinic acid calms thyroid response - more indicated for <strong>hyperthyroidism</strong> but no harm for hypo; use with <a href="?herb=109"><strong>Rosemary</strong></a> and <a href="?herb=134"><strong>Lemon Balm</strong></a>. For <strong>allergies</strong>: brain lymphatic support. Vulnerary in wound wash alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=88"><strong>Chickweed</strong></a>, <a href="?herb=81"><strong>St. John's Wort</strong></a>. Self Heal Flower Essence: spirit remedy for <strong>depression</strong>.$$
WHERE id = 2437;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Senna</strong> is a potent <strong>laxative</strong> for <strong>constipation</strong> - a last resort alongside <a href="?herb=205"><strong>Cascara Sagrada</strong></a>. <strong>Can easily become habit-forming - not for more than a few days at most.</strong>$$
