UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Shatavari</strong> (Asparagus racemosus) is the feminine counterpart to <a href="?herb=20"><strong>Ashwagandha</strong></a> - nourishing, very yin, deeply <strong>moistening</strong>, restorative calming <strong>adaptogen</strong>; <strong>reproductive and fertility tonic</strong>, <strong>hormone balancing</strong>, and <strong>aphrodisiac</strong>; traditionally a decoction combined with fat. Moistening adaptogen for dry constitution alongside <a href="?herb=17"><strong>Schizandra</strong></a>, Ginsengs, and <a href="?herb=78"><strong>Licorice</strong></a>. For <strong>perimenopause</strong>: brings juiciness to dry tissues in a drying phase of life. For <strong>thyroid</strong>: moistening adaptogen indicated when on the edge of burnout with dry tissues. For <strong>anxiety</strong> and reproductive issues from dry tissues; uterus tonifying; moistens vagina and GI tract. Cooling, moistening, relaxing for <strong>digestion</strong>: nourishing gut formula with <a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=127"><strong>Cardamom</strong></a> - appropriate for dry constitutions with GI inflammation or poor absorption; for <strong>Cold Dry Constipation</strong>. Lisa's adaptogen-nervine formula (digestive case): Shatavari 40-80 drops (60 mL), <a href="?herb=178"><strong>Milky Oats</strong></a> 25-50 drops (40 mL), <a href="?herb=2229"><strong>Gotu Kola</strong></a> 15-30 drops (20 mL); therapeutic dose = 4 droppers full (120 drops); originally included <a href="?herb=20"><strong>Ashwagandha</strong></a>, switched out due to irritability. Tonic tincture with <a href="?herb=178"><strong>Milky Oats</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, <a href="?herb=2653"><strong>Bleeding Heart</strong></a>, <a href="?herb=25"><strong>Black Cohosh</strong></a>, <a href="?herb=90"><strong>Linden</strong></a>. Post-menopausal dryness formula: Shatavari + <a href="?herb=20"><strong>Ashwagandha</strong></a> + <a href="?herb=2229"><strong>Gotu Kola</strong></a> (+ <a href="?herb=78"><strong>Licorice</strong></a> as demulcent). Healthy aging tea with <a href="?herb=1528"><strong>Jujube</strong></a>, <a href="?herb=1548"><strong>Goji</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>. Immunity with aging alongside <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=1528"><strong>Jujube</strong></a>, <a href="?herb=1548"><strong>Goji</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=26"><strong>Echinacea</strong></a>, <a href="?herb=99"><strong>Myrrh</strong></a> - moistening while stimulating immune function and addressing waste accumulation. Traditionally a decoction, not a tincture.$$
WHERE id = 852;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Shepherd's Purse</strong> is a <strong>styptic</strong>, <strong>constricting</strong> (tannin-rich), and powerful acute <strong>hemostatic</strong> herb - specific for stopping bleeding; listed alongside <a href="?herb=47"><strong>Cayenne</strong></a> and <a href="?herb=44"><strong>Yarrow</strong></a> as a styptic. <strong>Very effective for heavy bleeding - so effective it can clot up the uterus; only use in very heavy situations. It is not a constitutional tonic; reserve it for acute bleeding presentations.</strong> For <strong>kidney deficiency</strong>: adrenal and hormonal support. For <strong>kidney excess</strong>: diuretic cooler.$$
WHERE id = 71;

