UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Siberian Ginseng</strong> (Eleuthero) is a sweet, <strong>adaptogen</strong>, <strong>immune tonic</strong>, and <strong>lung tonic</strong> - the origin of the concept of adaptogens (developed for Russian athletes); lowers cortisol; "the White Rabbit - running around late; bend time, make more space in the day"; quality of "stretching time" - effect on perception of stress and mental capacity. For <strong>energy and stress resilience</strong>: increases exercise tolerance; enhances concentration; mobilizes oxygen to organs and tissues; strengthens digestion and kidney function; enhances overall resistance to disease; lowers lipids associated with arteriosclerosis; lowers cholesterol; improves ischemic heart disease; reduces stress-induced thrombosis. For <strong>blood sugar dysregulation</strong>: lowers cortisol and enhances insulin sensitivity - good for burnt-out, busy person with jittery blood sugar; sweet medicine; root requires decoction or double extraction; dose: tincture 1:4, 3-5 ml TID. For <strong>anxiety</strong> and emotional support: stress tincture at equal parts with <a href="?herb=13"><strong>Tulsi</strong></a>. Lung tonic alongside <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>. For <strong>common cold</strong> and <strong>influenza</strong>: immune tonic - use after the acute phase resolves. For female reproductive excess: anabolic cooler.$$
WHERE id = 9;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Silk Tassel</strong> (Garrya) is a <strong>relaxing</strong>, <strong>antispasmodic</strong> herb specifically indicated for <strong>smooth muscle spasm</strong>: intestines, vaginal cramps, and possibly restless leg; relaxes muscle cramps, spasms, and tension; only the male shrubs flower. For <strong>Upper GI excess with pain</strong> and <strong>Lower GI excess</strong>: antispasmodic.$$
WHERE id = 853;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Silk Tree</strong> (Albizia julibrissin / Mimosa Bark) - "the tree of joy" - is a <strong>spirit remedy</strong> and <strong>anxiolytic</strong> for <strong>depression</strong> and <strong>grief</strong>; for <strong>stagnant depression</strong> where trauma has become the focus of existence - especially PTSD, chronic unrelenting grief, depression with heartbreak, bad dreams, anger, and irritability; "utilize in all forms for collective happiness." Bark is stronger and grounding; flower is more uplifting; use 1:1 bark:flower. For <strong>grief</strong>: stress relief and grief processing alongside <a href="?herb=2653"><strong>Bleeding Heart</strong></a> and <a href="?herb=131"><strong>Motherwort</strong></a>; can be added to complex formulas addressing grief and emotional processing. As <strong>mast cell stabilizer</strong>: for <strong>eczema</strong> - reduces allergic response in the skin.$$
WHERE id = 2285;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Silk Tree</strong> (Albizia julibrissin / Mimosa) - "the tree of collective happiness" - is a <strong>spirit remedy</strong> and <strong>antidepressant</strong> herb; lifts the spirits in mild to moderate <strong>depression</strong>; for <strong>stagnant depression</strong> where trauma has become the focus of existence; bark is stronger and grounding, flower is more uplifting; use 1:1 bark:flower; can be used as flower, leaf, or root tincture - "utilize in all forms." For <strong>grief</strong>: alongside <a href="?herb=2653"><strong>Bleeding Heart</strong></a> and <a href="?herb=131"><strong>Motherwort</strong></a>.$$
WHERE id = 2746;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Skullcap</strong> is a <strong>nervine trophorestorative</strong>, <strong>relaxing nervine</strong>, <strong>antispasmodic</strong>, and <strong>nerve tonic</strong> - best as fresh tincture or tea (dried tincture not very effective). Key differential: lights, noises, and smells overwhelm; decision-making paralysis; recovery from mental breakdown or stimulant drugs; for too much caffeine. For <strong>acute anxiety</strong>: nervine relaxant for acute anxiety, anger, tremors, spasm, and nervous ticks; at high dose (4 droppers full) for shock, grief, and acute anxiety. For <strong>sleep</strong>: relaxing nervine; sleep tincture with <a href="?herb=983"><strong>Blue Vervain</strong></a> and <a href="?herb=137"><strong>Passionflower</strong></a> for restlessness before sleep; in Feri's stress glycerite with <a href="?herb=136"><strong>Catnip</strong></a> for nighttime sleep support; skullcap/catnip glycerite for post-menopausal sleep and restlessness; for anxiety-induced insomnia. For <strong>musculoskeletal</strong>: muscle relaxant; GI antispasmodic for cramping and spasm; spasms and shakiness. For <strong>heart bypass support</strong>: calming so the brain signals more efficiently. For <strong>urinary and bladder health</strong>: milder sedative supporting the nervous system. For <strong>kidney health</strong>: regulating the nervous system protects kidney function - the more one is in a hypertensive state, the more damage to the kidneys. For <strong>rheumatoid arthritis</strong>: nervine. For <strong>asthma</strong>: nervine. For <strong>emphysema</strong>: nervine. For <strong>neuritis</strong> (peripheral nerve inflammation): nerve tonic. Nervines for nervous system support alongside <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=137"><strong>Passionflower</strong></a>, <a href="?herb=983"><strong>Blue Vervain</strong></a>.$$
WHERE id = 142;
